const $=s=>document.querySelector(s);const palette=['#38554a','#a1addd','#b9cfa9','#d4aca0','#d4bf85'];const key='habit-notebook-v1';let data={habits:[],checks:{},todos:[]};let hasSavedData=false;try{const s=JSON.parse(localStorage.getItem(key));if(s&&Array.isArray(s.habits)&&s.checks&&Array.isArray(s.todos)){data=s;hasSavedData=true}}catch{}let view='habits',editing=null,color=palette[0],week=startWeek(new Date());function dateKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}function startWeek(d){const v=new Date(d.getFullYear(),d.getMonth(),d.getDate(),12);v.setDate(v.getDate()-v.getDay());return v}function day(i){const d=new Date(week);d.setDate(d.getDate()+i);return d}function weekNumber(d){const v=new Date(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate()+1));v.setUTCDate(v.getUTCDate()+4-(v.getUTCDay()||7));return Math.ceil((((v-new Date(Date.UTC(v.getUTCFullYear(),0,1)))/86400000)+1)/7)}function save(operation='save'){try{localStorage.setItem(key,JSON.stringify(data));return true}catch{analytics.track('storage_failed',{operation});toast('保存失败，请检查浏览器储存空间');return false}}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2600)}function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
function formatReminder(value){if(!value)return '设置提醒';const d=new Date(value);if(Number.isNaN(d.getTime()))return '设置提醒';const today=dateKey(new Date()),tomorrow=dateKey(new Date(Date.now()+86400000)),dkey=dateKey(d);const time=d.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false});return dkey===today?'今天 '+time:dkey===tomorrow?'明天 '+time:(d.getMonth()+1)+'月'+d.getDate()+'日 '+time}
function askReminderPermission(){if(!('Notification'in window)||Notification.permission!=='default')return;Notification.requestPermission().then(permission=>{if(permission==='denied')toast('通知未开启，到点时请保持页面打开')}).catch(()=>{})}
