function circle(done,label,c,action){const b=el('button','check');b.setAttribute('aria-pressed',String(done));b.setAttribute('aria-label',label);b.style.setProperty('--color',c);b.innerHTML='<span class="ring"><svg viewBox="0 0 24 24"><path d="m5 12 5 6L20 5"/></svg></span>';b.onclick=action;return b}function habitStatus(value){return value===true||value==='done'?'done':value==='missed'?'missed':'empty'}function habitCircle(status,label,c,action){const b=el('button','check habit-check state-'+status);b.setAttribute('aria-pressed',String(status==='done'));b.setAttribute('aria-label',label+'：'+(status==='done'?'已完成':status==='missed'?'未完成':'未标记'));b.style.setProperty('--color',c);b.innerHTML='<span class="ring"><svg class="tick" viewBox="0 0 24 24"><path d="m5 12 5 6L20 5"/></svg><svg class="cross" viewBox="0 0 24 24"><path d="M6 6 18 18M18 6 6 18"/></svg></span>';b.onclick=action;return b}function cycleHabitCheck(id,date){if(!data.habits.some(h=>h.id===id)||!/^\d{4}-\d{2}-\d{2}$/.test(date))throw Error('无效打卡数据');const k=id+':'+date,current=habitStatus(data.checks[k]);if(current==='empty')data.checks[k]='done';else if(current==='done')data.checks[k]='missed';else delete data.checks[k];if(save('habit_check'))trackCheck(current,habitStatus(data.checks[k]),date);render()}function setCheck(id,date,value){if(!data.habits.some(h=>h.id===id)||!/^\d{4}-\d{2}-\d{2}$/.test(date)||typeof value!=='boolean')throw Error('无效打卡数据');const k=id+':'+date,current=habitStatus(data.checks[k]);if(value)data.checks[k]='done';else delete data.checks[k];if(save('habit_check'))trackCheck(current,habitStatus(data.checks[k]),date);render()}
